"""Alert data schema for threat detection engine."""

from datetime import datetime, timezone
import hashlib
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, ConfigDict, Field


class Alert(BaseModel):
    """Normalized security alert generated by deterministic detection rules."""

    model_config = ConfigDict(extra="allow", validate_assignment=True)

    alert_id: str = Field(..., description="Unique alert identifier")
    rule_id: str = Field(..., description="Detection rule identifier (e.g. RULE-001)")
    rule_version: str = Field(default="1.0", description="Rule specification version")
    rule_name: str = Field(..., description="Human-readable rule name")
    severity: str = Field(..., description="Severity level: low, medium, high, critical")
    first_observed: str = Field(..., description="Earliest contributing event timestamp (UTC ISO-8601)")
    last_observed: str = Field(..., description="Latest contributing event timestamp (UTC ISO-8601)")
    related_event_ids: List[str] = Field(
        default_factory=list,
        description="List of raw event IDs providing forensic evidence",
    )
    explanation: str = Field(..., description="Objective, evidence-based narrative explanation")
    supporting_evidence: Dict[str, Any] = Field(
        default_factory=dict,
        description="Structured supporting metrics (e.g. failure count, time delta, commands)",
    )
    entities: Dict[str, Any] = Field(
        default_factory=dict,
        description="Associated security entities (e.g. host, username, source_ip)",
    )
    confidence: float = Field(
        default=0.8,
        ge=0.0,
        le=1.0,
        description="Calculated detection confidence score (0.0 - 1.0)",
    )
    risk_score: float = Field(
        default=50.0,
        ge=0.0,
        le=100.0,
        description="Estimated risk prioritization score (0 - 100)",
    )
    created_at: str = Field(
        default_factory=lambda: datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        description="Alert creation timestamp (UTC ISO-8601)",
    )
    fingerprint: Optional[str] = Field(
        default=None,
        description="Stable deduplication fingerprint across alert occurrences",
    )

    @classmethod
    def create(
        cls,
        rule_id: str,
        rule_name: str,
        severity: str,
        first_observed: str,
        last_observed: str,
        related_event_ids: List[str],
        explanation: str,
        supporting_evidence: Dict[str, Any],
        entities: Dict[str, Any],
        confidence: float = 0.8,
        risk_score: float = 50.0,
        rule_version: str = "1.0",
    ) -> "Alert":
        """Factory method computing a deterministic alert fingerprint and unique alert_id."""
        # Compute deterministic fingerprint from rule_id and primary entity keys
        primary_entity = (
            entities.get("source_ip")
            or entities.get("username")
            or entities.get("host")
            or "global"
        )
        fp_hasher = hashlib.sha256()
        fp_hasher.update(rule_id.encode("utf-8"))
        fp_hasher.update(b"|")
        fp_hasher.update(str(primary_entity).lower().encode("utf-8"))
        fingerprint = f"fp_{fp_hasher.hexdigest()[:24]}"

        # Alert ID incorporates fingerprint + first_observed timestamp
        alert_hasher = hashlib.sha256()
        alert_hasher.update(fingerprint.encode("utf-8"))
        alert_hasher.update(b"|")
        alert_hasher.update(first_observed.encode("utf-8"))
        alert_hasher.update(b"|")
        alert_hasher.update(last_observed.encode("utf-8"))
        alert_id = f"alt_{alert_hasher.hexdigest()[:24]}"

        return cls(
            alert_id=alert_id,
            rule_id=rule_id,
            rule_version=rule_version,
            rule_name=rule_name,
            severity=severity,
            first_observed=first_observed,
            last_observed=last_observed,
            related_event_ids=related_event_ids,
            explanation=explanation,
            supporting_evidence=supporting_evidence,
            entities=entities,
            confidence=confidence,
            risk_score=risk_score,
            fingerprint=fingerprint,
        )
